import type { On, PluginOptions, RenderSurface } from 'claude-code'
import { isCheckpointing } from './core/checkpointing'
import { commandGlyphOf } from './core/command-glyph'
import { DIRECTIVE_OPS, withoutDirectives } from './core/directive'
import type { Host } from './core/host'
import { isRecord } from './core/is-record'
import { createRaven, type Raven } from './core/raven'
import { settingsOf } from './core/settings'
import type { ToolEvent } from './core/triggers'
import { capabilitiesOf, type Kit, type Ui } from './core/view'
import {
  COMMAND,
  COMMAND_DESCRIPTION,
  NAME,
  PANE_IDS,
  PANE_SUBCOMMANDS,
  TOOL_NAME,
  toolNameOf,
} from './names'
import { styleOf } from './ui/style'
import { commandOutputRow } from './views/band'

// The plugin's own name is only known once `$` binds, so the tool's full name cannot be a static
// string here; this matches any plugin's `show` tool as `tool.call`'s matcher must be static.
const TOOL_MATCH = new RegExp(`^mcp__.+__${TOOL_NAME}$`)

const TOOL_DESCRIPTION =
  'Show something to the user in the Raven preview pane beside the transcript, where they can ' +
  'comment on it. Use it whenever you produce something the user should read or decide on rather ' +
  'than scroll past: a plan, spec, design, report or any doc you wrote (`show`), a summary or ' +
  "checklist you compose (`note`), one file's changes (`diff`), or a pane by name (`open`). Some " +
  'docs open by themselves, and the result of the edit that wrote them says so; no such note means ' +
  'it was not shown, so show it. `comments` fetches pending comments on demand.'

/** The context block every conversation carries: that the pane exists, and what it is for. */
const CONTEXT_TEXT =
  'Raven docks a preview pane beside the transcript: the live diff, and rendered plans and docs. ' +
  'The user can comment on diff hunks and doc sections there. Use the Raven show tool to put ' +
  'something in front of them.'

/** The line Raven's entry in the MCP server instructions reads instead of the engine's stock one. */
const INSTRUCTIONS_TEXT =
  "Raven's show tool puts a plan, doc, note or diff in the preview pane beside the transcript, " +
  'and reads the review comments the user leaves there.'

/** The engine's stock line for a plugin's registered tools, which says nothing about them. */
const stockInstructionsOf = (plugin: string) =>
  `Tools registered by the ${plugin} plugin through $.tool.register.`

/** The question tool whose answer, given to the main loop, carries the person's pending review. */
const ASK_TOOL = 'AskUserQuestion'

const TOOL_INPUT_SCHEMA = {
  type: 'object',
  properties: {
    op: {
      enum: [...DIRECTIVE_OPS],
      description:
        "'show' renders a file at `path`; 'note' renders the markdown you compose; 'diff' opens " +
        "the diff, optionally at `path`; 'comments' reads the user's pending review comments; " +
        "'open' switches the pane to `pane` (leaving it showing if it already is).",
    },
    path: {
      type: 'string',
      description: 'A file path, relative to the session cwd unless absolute.',
    },
    pane: {
      enum: [...PANE_SUBCOMMANDS],
      description: 'The pane to show, for `op: "open"`.',
    },
    markdown: { type: 'string', description: 'Markdown to render, for `op: "note"`.' },
    title: {
      type: 'string',
      description: 'A title for the pane, for `op: "show"` or `op: "note"`.',
    },
  },
  required: ['op'],
}

/**
 * Raven's hooks: binds the engine once at `session.start`, then forwards commands, tool calls,
 * prompts and pane drawing to the controller in `core/raven`.
 */
export function register(on: On, options: PluginOptions) {
  const settings = settingsOf(options)
  const style = styleOf(settings.cardStyle)
  let raven: Raven | null = null

  /**
   * Notes the viewport off any `ui.render` event and builds its `Kit` around `resolve` (always
   * `() => $.ui.resolve(e)` at the call site: the sandbox forbids passing `$` itself), whose `ui`
   * resolves lazily so a handler whose guard declines to draw (a hidden pane, a band a survey
   * suppresses) never pays for `$.ui.resolve`. `capabilities` is computed once here, off
   * `surface`, not off which elements `resolve()` happens to hand back. See `core/view.ts`.
   */
  function kitOf(
    viewport: { columns?: number } | undefined,
    resolve: () => unknown,
    columns: number,
    rows: number,
    surface: RenderSurface,
    requestId: string,
  ): Kit {
    raven?.noteViewport(viewport?.columns)
    let cached: Ui | undefined
    return {
      get ui() {
        if (cached === undefined) cached = resolve() as unknown as Ui
        return cached
      },
      columns,
      rows,
      capabilities: capabilitiesOf(surface, settings.keyboardControls),
      style,
      press: (id, onPress) => raven?.registerPress(requestId, id, onPress),
    }
  }

  on('session.start', async ($, e, next) => {
    const bound: Host = {
      run: (argv, stdin) => $.process.run(argv, stdin === undefined ? undefined : { stdin }),
      readFile: async path => {
        const text = await $.fs.read(path)
        return typeof text === 'string' ? text : ''
      },
      after: (ms, fn) => $.clock.after(ms, fn),
      redraw: () => $.ui.invalidate('ui.render'),
      openPane: async pane => (await $.ui.open(pane)).isPlaced,
      closePane: id => $.ui.close({ id }),
      shownPaneIds: async () =>
        new Set((await $.ui.panes()).filter(pane => pane.isShown).map(pane => pane.id)),
      focus: async (paneId, key) => {
        await $.ui.focus({ requestId: paneId, key })
      },
      storeGet: key => $.store.get(key),
      storeSet: (key, value) => $.store.set(key, value),
      submitPrompt: async text => {
        await $.prompt.submit({ text })
      },
      cwd: () => $.session.cwd(),
      fork: async prompt => {
        const result = await $.model.fork({ prompt })
        return result.isAnswered ? result.text : null
      },
      status: text => $.ui.status(text),
      fillPrompt: async text => {
        const result = await $.prompt.fill({ text, mode: 'replace' })
        return { isFilled: result.isFilled, refusal: result.refusal }
      },
      toast: text => $.ui.toast(text),
      messages: () => $.session.messages(),
      debug: text => $.ui.log(text, { to: 'debug' }),
      readGlobalConfig: async () => {
        const home = await $.env.get('HOME')
        if (home === undefined) return null
        try {
          const text = await $.fs.read(`${home}/.claude.json`)
          return JSON.parse(typeof text === 'string' ? text : '')
        } catch {
          return null
        }
      },
      isCheckpointing: async () =>
        isCheckpointing(
          await $.settings.read(),
          await $.env.get('CLAUDE_CODE_DISABLE_FILE_CHECKPOINTING'),
        ),
    }

    const created = createRaven(bound, settings, () => Date.now())
    await $.command.register({
      name: COMMAND,
      description: COMMAND_DESCRIPTION,
      argumentHint: created.argumentHint,
    })
    await $.tool.register({
      name: TOOL_NAME,
      description: TOOL_DESCRIPTION,
      inputSchema: TOOL_INPUT_SCHEMA,
    })
    raven = created

    return next(e)
  })

  on('command.run', { command: COMMAND }, async ($, e, next) => {
    if (!raven) return next(e)
    const result = await raven.command(e.args)
    return { text: result.text }
  })

  on('ui.render', { component: 'Pane' }, async ($, e, next) => {
    const kit = kitOf(
      e.viewport,
      () => $.ui.resolve(e),
      e.props.bodyColumns,
      e.props.scroll.bodyRows,
      e.surface,
      e.requestId,
    )
    if (!raven || !PANE_IDS.includes(e.requestId)) return next(e)
    const drawn = raven.render(e.requestId, kit)
    return drawn ?? next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const kit = kitOf(
      e.viewport,
      () => $.ui.resolve(e),
      e.props.bodyColumns,
      e.props.maxRows,
      e.surface,
      e.requestId,
    )
    if (!raven) return next(e)
    const drawn = await raven.band(kit, e.props.hasSurvey, e.requestId)
    return drawn ?? next(e)
  })

  on(
    'ui.render',
    { component: 'CommandOutput', props: { command: COMMAND } },
    async ($, e, next) => {
      const kit = kitOf(e.viewport, () => $.ui.resolve(e), 0, 0, e.surface, e.requestId)
      if (!raven) return next(e)
      return commandOutputRow(kit, {
        text: e.props.text,
        isErrored: e.props.isErrored,
        glyph: commandGlyphOf(raven.resultKindOf(e.props.text)),
      })
    },
  )

  // A `Client` pill's press (`surface/strip.tsx` posts `{ press: id }`) from a pane or the band. `data` came from code, so
  // it is validated; a stale or unknown id is ignored. Answers `{}` either way: nothing to hand back.
  on('ui.message', ($, e, next) => {
    const data = e.data
    if (raven && isRecord(data) && typeof data.press === 'string') {
      raven.press(e.requestId, data.press)
      return {}
    }
    return next(e)
  })

  on('ui.scroll', { requestId: PANE_IDS }, ($, e, next) => {
    if (!raven || e.origin.kind !== 'person' || !raven.scroll(e.requestId, e.by)) return next(e)
    $.ui.invalidate('ui.render')
    return {}
  })

  // A fork of its own answer raises no turn.complete the types promise, but the flag inside
  // `turnCompleted` guards it either way; `next(e)` runs first so this never slows the turn. Every
  // main-loop turn end reaches it, not just `reason: 'answer'`, so the live feed resets even on an
  // interrupted or errored turn; `turnCompleted` itself only forks to resolve sent comments when
  // the turn actually answered.
  on('turn.complete', ($, e, next) => {
    const result = next(e)
    if (raven && e.agentId === undefined) void raven.turnCompleted(e)
    return result
  })

  on('ui.close', { id: PANE_IDS }, async ($, e, next) => {
    const result = await next(e)
    if (result.deny === undefined) raven?.paneClosed(e.id)
    return result
  })

  // The tool's schema and description sit in the prompt's tool list instead of behind ToolSearch,
  // so the model knows the pane is there without first going looking for it.
  on('tool.describe', { tool: TOOL_MATCH }, async ($, e, next) => {
    const result = await next(e)
    return e.tool === toolNameOf($.plugin.name) ? { ...result, isDeferred: false } : result
  })

  on('prompt.context', async ($, e, next) => {
    const result = await next(e)
    return { ...result, blocks: [...result.blocks, { name: NAME, text: CONTEXT_TEXT }] }
  })

  // The engine lists each plugin with registered tools under `## <plugin>` and a stock line; only
  // Raven's own line is rewritten, and an attachment without it passes through untouched.
  on('prompt.attachment', { type: 'mcp_instructions_delta' }, async ($, e, next) => {
    const result = await next(e)
    const stock = stockInstructionsOf($.plugin.name)
    return result.text?.includes(stock)
      ? { ...result, text: result.text.replace(stock, INSTRUCTIONS_TEXT) }
      : result
  })

  // Registered before the catch-all below: answering here without calling `next` keeps that hook
  // from also reacting to this call (a call no hook answers fails, so this one must answer).
  on('tool.call', { tool: TOOL_MATCH }, async ($, e, next) => {
    if (e.tool !== toolNameOf($.plugin.name) || !raven) return next(e)
    try {
      const text = await raven.runTool(e)
      return { result: text, text }
    } catch (error) {
      return { deny: error instanceof Error ? error.message : String(error) }
    }
  })

  on('tool.call', async ($, e, next) => {
    const result = await next(e)
    if (!raven) return result

    const isLanded = result.deny === undefined && result.isError !== true
    const output = isLanded && isRecord(result.result) ? result.result : {}
    const event: ToolEvent = {
      tool: e.tool,
      input: isRecord(e) ? e : {},
      isLanded,
      agentId: e.agentId,
      stdout: typeof output.stdout === 'string' ? output.stdout : undefined,
      result: isLanded ? result.result : undefined,
    }

    const outcome = await raven.afterTool(event)
    const notes = [...outcome.notes]
    // An answer the person gave the main loop's question carries their pending review, as a prompt
    // they type does, so notes left before the question appeared are not held back. (The question's
    // dialog holds the keyboard, so no note can be typed while it is open.)
    if (isLanded && e.tool === ASK_TOOL && e.agentId === undefined) {
      const review = await raven.takeAnswerContext()
      if (review !== undefined) notes.push(review)
    }
    if (result.deny !== undefined) return result
    const withNotes =
      notes.length > 0 ? { ...result, context: [...(result.context ?? []), ...notes] } : result
    const ack = outcome.text
    if (ack === undefined || !isLanded || !isRecord(result.result)) return withNotes
    // The model reads Bash's result from its `stdout`, so the ack replaces the CLI's lines there;
    // anything else the command printed stays.
    const rest = withoutDirectives(event.stdout ?? '')
    const text = rest === '' ? ack : `${rest}\n${ack}`
    return { ...withNotes, result: { ...result.result, stdout: text }, text }
  })

  // Plan mode's notes name the plan file wherever plans are kept; observed, never rewritten.
  on(
    'prompt.attachment',
    { type: ['plan_mode', 'plan_mode_exit', 'plan_mode_reentry'] },
    async ($, e, next) => {
      const result = await next(e)
      if (raven && e.agentId === undefined && e.detail) {
        await raven.planNoted({ type: e.type, ...e.detail })
      }
      return result
    },
  )

  // Only a prompt the person sent (typed, or through Remote Control) carries the review. The
  // toast only fires once the prompt actually went through: a dropped prompt restores the
  // comments it carried instead (R5).
  on('prompt.submit', async ($, e, next) => {
    const isPersons = e.origin.kind === 'composer' || e.origin.kind === 'bridge'
    const carried = isPersons ? await raven?.takePromptContext() : undefined
    if (!carried) return next(e)
    try {
      const result = await next({ ...e, context: [...(e.context ?? []), carried.text] })
      if (result.drop === undefined) raven?.noteCarried(carried.count)
      else raven?.restoreCarried(carried.ids)
      return result
    } catch (error) {
      raven?.restoreCarried(carried.ids)
      throw error
    }
  })
}

files.hooks/core/command-glyph.ts:
/** The text `/raven` answers when the terminal is too narrow to dock the pane. */
export const NARROW_TEXT = 'Widen the terminal to dock the Raven pane'

/**
 * What a `/raven` command run resolved to. `info` is the fallback for a `CommandOutput` row whose
 * text no `command()` call in this session produced (a replayed transcript, a reloaded module).
 */
export type CommandKind = 'shown' | 'hidden' | 'narrow' | 'error' | 'info'

export type CommandResult = { kind: CommandKind; text: string }

const GLYPHS: Record<CommandKind, string> = {
  shown: '◆',
  hidden: '◇',
  narrow: '!',
  error: '!',
  info: '◆',
}

/** Which glyph leads a `/raven` command's output row, by its result's kind. */
export function commandGlyphOf(kind: CommandKind): string {
  return GLYPHS[kind]
}

