import type { RenderElement, Timer, TurnCompleteInput } from 'claude-code'
import { existingPathsOf } from '../git/load'
import { DIFF_PANEL_WARNING } from '../names'
import { addressedIdsOf, type Comment, reviewTextOf } from '../review/comments'
import { resolvePromptOf } from '../review/resolve'
import { createReview } from '../review/review'
import { paneFill } from '../ui/pane-fill'
import { createDiffView } from '../views/diff-view'
import { createDocView, type Doc } from '../views/doc-view'
import { createTasksView } from '../views/tasks-view'
import { createTreeView } from '../views/tree-view'
import { shouldAutoOpen } from './auto-open'
import { createBandState } from './band-state'
import { coversRavenDock } from './checkpointing'
import { type CommandKind, type CommandResult, NARROW_TEXT } from './command-glyph'
import { type Directive, directiveOf } from './directive'
import { countOf } from './format'
import { type Host, loggedAs } from './host'
import { createPresses } from './presses'
import type { RavenSettings } from './settings'
import {
  type Action,
  actionsOf,
  type PlanNote,
  planActionsOf,
  type ToolEvent,
  triggersOf,
} from './triggers'
import type { Kit, View } from './view'

/**
 * What a finished tool call means for the model: `text` replaces a shell call's directive lines,
 * `notes` are read after the result (the user never sees them).
 */
export type ToolOutcome = { text?: string; notes: readonly string[] }

/** The engine-facing surface of Raven; `register` forwards engine events here and nothing else. */
export type Raven = {
  /** The `/raven` argument hint: each view's subcommand, then `send`. */
  argumentHint: string
  command: (args: string) => Promise<CommandResult>
  /**
   * Reacts to a finished tool call: replacement result text for a directive, and notes telling the
   * main loop what Raven opened by itself. Never rejects: a failure goes to the debug log.
   */
  afterTool: (event: ToolEvent) => Promise<ToolOutcome>
  /**
   * Learns the plan file plan mode named, so its edits render live; opens it on exit/re-entry.
   * Never rejects: a failure goes to the debug log.
   */
  planNoted: (note: PlanNote) => Promise<void>
  /** Runs the `show` tool's input as a directive; throws on input `directiveOf` rejects. */
  runTool: (input: unknown) => Promise<string>
  /**
   * Hidden context the next prompt carries: the live pending comments, which it marks sent (a
   * stale pending comment among them moves to 'open' instead, never riding). `undefined` when
   * there is nothing live to carry. `ids` is the taken batch, for `restoreCarried` if the prompt
   * this primes is later dropped.
   */
  takePromptContext: () => Promise<
    { text: string; count: number; ids: readonly string[] } | undefined
  >
  /** The prompt `takePromptContext` primed went through: toasts how many comments it carried. */
  noteCarried: (count: number) => void
  /**
   * The main loop's AskUserQuestion was answered: takes the live pending review for the answer's
   * hidden context, and toasts it. Never rejects: a failure is logged, and the review stays pending.
   */
  takeAnswerContext: () => Promise<string | undefined>
  /** The prompt `takePromptContext` primed was dropped: undoes it, restoring `ids` to pending. */
  restoreCarried: (ids: readonly string[]) => void
  /**
   * Reacts to a finished main-loop turn: always resets the live feed (clears this turn's edited
   * marks and resumes following); only an answered turn also forks once to learn which sent
   * comments it addressed.
   */
  turnCompleted: (turn: TurnCompleteInput) => Promise<void>
  render: (paneId: string, kit: Kit) => RenderElement | null
  /**
   * Runs the handler a `Client` pill's `{ press: id }` post names, in the pane `paneId` drew it in;
   * false when the id is not (or no longer) drawn there.
   */
  press: (paneId: string, id: string) => boolean
  /** Registers the handler for a pill `id` drawn in `paneId`'s current render (`Kit.press`). */
  registerPress: (paneId: string, id: string, onPress: () => void) => void
  /** Moves a pane's own scroll by `by` rows; true when its view handled the move. */
  scroll: (paneId: string, by: number) => boolean
  paneClosed: (paneId: string) => void
  /** Records the terminal's width off any `ui.render` Raven sees, for the auto-open gate. */
  noteViewport: (columns: number | undefined) => void
  /**
   * The `AbovePrompt` band: null while a survey holds it, `maxRows` is too small, nothing is
   * pending, or a Raven pane is already visible (not just open behind another tab).
   */
  band: (kit: Kit, hasSurvey: boolean, requestId: string) => Promise<RenderElement | null>
  /** The kind a past `command()` call resolved `text` to; `'info'` when no call produced it. */
  resultKindOf: (text: string) => CommandKind
}

const REFRESH_DEBOUNCE_MS = 300

/** Told to the main loop when the first edit opened the diff by itself. */
export const DIFF_NOTE =
  "Raven: the session's diff is now live in the Raven pane beside the transcript."

/** Told to the main loop when a doc it wrote opened by itself. */
export const docNoteOf = (path: string) =>
  `Raven: ${path} is shown rendered in the Raven pane beside the transcript, and the user can ` +
  'comment on its sections there. If it is something they should approve, say so in one line and ask with ' +
  'AskUserQuestion ("Looks good, proceed" / "I\'ll comment in the pane"); on the second, end your ' +
  'turn asking them to leave notes and reply, and the notes arrive with their reply.'

/**
 * Told to the main loop when plan mode's own plan opened by itself: plan mode approves through its
 * own exit, so this names no question to ask.
 */
export const planNoteOf = (path: string) =>
  `Raven: the plan ${path} is shown rendered in the Raven pane beside the transcript; the user ` +
  'can comment on its sections there, and their notes arrive with their next reply.'

/** What one action did: `text` answers a directive, `note` tells the model about an unasked open. */
type ActionOutcome = { text?: string; note?: string }

const toastOfCarried = (count: number, carrier: string) =>
  `Raven: ${countOf(count, 'review comment')} sent with ${carrier}`
const SEND = 'send'

const REFUSAL_TEXTS: Record<'no_composer' | 'dialog', string> = {
  no_composer: 'no prompt box in this session',
  dialog: 'a dialog has the keyboard',
}

export function createRaven(host: Host, settings: RavenSettings, now: () => number): Raven {
  const review = createReview(host, now)
  const diff = createDiffView(
    host,
    review,
    {
      send: () => void sendReview(),
      editAndSend: () => void editAndSend(),
      focus: key => void focusIn(diff, key),
    },
    now,
    { splitColumns: settings.splitColumns },
  )
  const doc = createDocView(host, review, { focus: key => void focusIn(doc, key) }, now)
  const tree = createTreeView(host, { open: path => void showDoc({ kind: 'file', path }) })
  const tasksView = createTasksView(host)
  const views: readonly View[] = [diff, doc, tree, tasksView]

  const open = new Set<string>()
  let refreshTimer: Timer | null = null
  let hasAutoOpened = false
  // Every file the Doc view has shown, and whether the main loop has been told so (by a note, or by
  // its own `show` call's result). A watched doc opens by itself only the first time, so later edits
  // reload it in place instead of pulling it in front of a pane the person switched to; a doc a
  // subagent's edit opened stays 'shown' until the main loop's first edit of it names it.
  const docs = new Map<string, 'shown' | 'told'>()
  let hasOpenedTasks = false
  let hasWarnedDiffPanel = false
  // Guards the fork below from re-entering itself and caps it at one per sent batch.
  let isResolving = false
  const planPaths = new Set<string>()
  const triggers = triggersOf(settings)
  // The kind the most recent `command()` call resolved each reply text to, for a `CommandOutput`
  // row the engine asks Raven to redraw without re-running the command.
  const resultKindByText = new Map<string, CommandKind>()
  const presses = createPresses()

  const bandState = createBandState(host, review, {
    openDiff: async () => {
      await showDiff()
    },
    openDoc: async () => {
      await show(doc)
    },
    sendReview,
  })

  // Kicked off at session start rather than waiting for the first `AbovePrompt` render or prompt
  // submit to need it: by the time either happens, the common case already has it loaded.
  // `ensureReviewLoaded` is idempotent, so the `await` each still does is then a no-op; this
  // only spares the *first* one from paying for the git read itself.
  void bandState.ensureReviewLoaded()

  /**
   * Once per module instance: warns when the built-in diff panel will cover Raven's dock. Never
   * throws, so a failed check never blocks the command or edit that triggered it.
   */
  async function warnDiffPanelOnce(): Promise<void> {
    if (hasWarnedDiffPanel) return
    hasWarnedDiffPanel = true
    try {
      const [globalConfig, checkpointing] = await Promise.all([
        host.readGlobalConfig(),
        host.isCheckpointing(),
      ])
      if (coversRavenDock(globalConfig, checkpointing)) host.toast(DIFF_PANEL_WARNING)
    } catch (error) {
      host.debug(`raven: diff panel check failed: ${String(error)}`)
    }
  }

  const takeReviewText = () => reviewTextOf(review.take())

  /**
   * A pending comment is live when it has a `section` (a doc comment, always live); `known` (the
   * diff's `knownPaths` at call time) is null (no live git list to check against: a turn source,
   * or nothing loaded yet); its path is among those known paths (which include a renamed file's
   * `oldPath`); or `existing` says the file is still there: checked only for comments `known`
   * doesn't already cover (R32: it's the diff moving past a file, not the file being gone, that
   * stops meaning "stale"). `existing` null (the check never ran, or failed) never counts against
   * a comment: fail open, same as `known` null. Only a comment whose file is truly gone moves to
   * 'open' by `review.take`, rather than riding the prompt silently.
   */
  const isLiveComment =
    (known: ReadonlySet<string> | null, existing: ReadonlySet<string> | null) =>
    (comment: Comment) =>
      comment.section !== undefined ||
      known === null ||
      known.has(comment.path) ||
      existing === null ||
      existing.has(comment.path)

  /** Forks once to ask which sent comments the finished turn addressed, then marks them. */
  async function resolveSent(): Promise<void> {
    const sent = review.sent()
    if (sent.length === 0 || isResolving) return
    isResolving = true
    // Captured before the fork: a newer batch sent while this fork is in flight must not be
    // touched by the reply this one gets back.
    const batchIds = sent.map(comment => comment.id)
    try {
      const reply = await host.fork(resolvePromptOf(sent))
      // No bracketed array in the reply means it was unparseable, not "nothing addressed"; leave
      // the comments sent rather than bouncing every one of them to 'open'.
      if (reply !== null && /\[[\s\S]*\]/.test(reply)) {
        review.resolveBatch(batchIds, addressedIdsOf(reply, batchIds))
        host.redraw()
      }
    } catch (error) {
      host.debug(`raven: resolving sent comments failed: ${String(error)}`)
    } finally {
      isResolving = false
    }
  }

  function cancelRefresh() {
    refreshTimer?.cancel()
    refreshTimer = null
  }

  /** Submits the pending review as a visible prompt, so the person sees what Claude was asked. */
  async function sendReview(): Promise<boolean> {
    const text = takeReviewText()
    if (text !== undefined) await host.submitPrompt(text)
    return text !== undefined
  }

  const refusalTextOf = (refusal: 'no_composer' | 'dialog' | undefined) =>
    (refusal && REFUSAL_TEXTS[refusal]) ?? 'the fill was refused'

  /** Fills the prompt box with the pending review so the person can edit it before sending. */
  async function editAndSend(): Promise<void> {
    const taken = review.take()
    const text = reviewTextOf(taken)
    if (text === undefined) return
    const filled = await host.fillPrompt(text)
    if (!filled.isFilled) {
      review.restore(taken.map(comment => comment.id))
      host.toast(`Raven: could not fill the prompt (${refusalTextOf(filled.refusal)})`)
    }
  }

  /**
   * Shows a view's pane, bringing it forward when it is a tab behind another; false when the
   * terminal is too narrow to dock it.
   */
  const isPaneShown = async (id: string) => (await host.shownPaneIds()).has(id)

  async function show(view: View, focus?: true): Promise<boolean> {
    if (open.has(view.pane.id)) {
      if (!focus && (await isPaneShown(view.pane.id))) return true
      // Reopening an open id only retitles it; a fresh open brings a background tab forward.
      if (!focus) await host.closePane(view.pane.id)
    }
    // Marked before the open: the engine draws the pane while `openPane` is in flight.
    open.add(view.pane.id)
    const isPlaced = await host.openPane({ ...view.pane, holdToasts: true, focus })
    // A pane left waiting would seat itself on a later resize; withdraw it instead.
    if (!isPlaced) await host.closePane(view.pane.id)
    return isPlaced
  }

  async function hide(view: View) {
    await host.closePane(view.pane.id)
    open.delete(view.pane.id)
    host.redraw()
  }

  /** The keyboard is the person's: an element can take it only once its pane asked for focus. */
  async function focusIn(view: View, key: string) {
    if (await show(view, true)) {
      await host
        .focus(view.pane.id, key)
        .catch(error => host.debug(`raven: focus failed: ${String(error)}`))
    }
  }

  function scheduleRefresh() {
    cancelRefresh()
    refreshTimer = host.after(REFRESH_DEBOUNCE_MS, () => {
      refreshTimer = null
      if (open.has(diff.pane.id)) void diff.refresh()
      if (open.has(tree.pane.id)) void tree.refresh()
    })
  }

  async function showDiff(path?: string) {
    cancelRefresh()
    await diff.refresh()
    if (open.has(tree.pane.id)) void tree.refresh()
    if (path) diff.reveal(path)
    return show(diff)
  }

  async function showDoc(shown: Doc) {
    await doc.show(shown)
    bandState.noteDocShown(
      shown.kind === 'file' ? shown.path : undefined,
      await isPaneShown(doc.pane.id),
    )
    const isShown = await show(doc)
    // A show the terminal was too narrow for is not counted, so the next edit tries again.
    if (isShown && shown.kind === 'file' && !docs.has(shown.path)) docs.set(shown.path, 'shown')
    return isShown
  }

  async function showTree() {
    await tree.refresh({ force: true })
    return show(tree)
  }

  const shownText = (isShown: boolean, what: string) =>
    isShown
      ? `Shown in the Raven pane: ${what}.`
      : `Raven could not dock its pane (the terminal is too narrow): ${what} was not shown.`

  /** Shows `view` the way its slash command does, minus the toggle: always leaves it visible. */
  const showView = (view: View) =>
    view === diff ? showDiff() : view === tree ? showTree() : show(view)

  function viewOf(subcommand: string): View {
    const view = views.find(each => each.subcommand === subcommand)
    if (!view) throw new Error(`Raven has no pane "${subcommand}"`)
    return view
  }

  async function runDirective(directive: Directive): Promise<string> {
    switch (directive.op) {
      case 'show': {
        const isShown = await showDoc({
          kind: 'file',
          path: directive.path,
          title: directive.title,
        })
        if (isShown) docs.set(directive.path, 'told')
        return shownText(isShown, directive.path)
      }
      case 'note':
        return shownText(
          await showDoc({ kind: 'note', markdown: directive.markdown, title: directive.title }),
          directive.title ?? 'the note',
        )
      case 'diff':
        return shownText(await showDiff(directive.path), 'the diff')
      case 'open':
        return shownText(await showView(viewOf(directive.pane)), `the ${directive.pane} pane`)
      case 'comments':
        return takeReviewText() ?? 'The user has no pending review comments.'
    }
  }

  /** A relative `path` is the tool's own, resolved against the session's cwd, not the CLI's shell. */
  async function resolveDirective(directive: Directive): Promise<Directive> {
    if (directive.op !== 'show' && directive.op !== 'diff') return directive
    const { path } = directive
    if (path === undefined || path.startsWith('/')) return directive
    return { ...directive, path: `${await host.cwd()}/${path}` }
  }

  /** Every pane Raven opens unasked goes through this one gate. */
  const mayAutoOpen = () => shouldAutoOpen(settings, bandState.viewportColumns())

  /** `isMainLoop`: the action came from the main loop's own tool call, whose result a note can ride. */
  async function runAction(action: Action, isMainLoop: boolean): Promise<ActionOutcome> {
    switch (action.kind) {
      case 'refresh-diff':
        if (action.path !== undefined) diff.noteEdited(action.path)
        if (open.has(diff.pane.id) || open.has(tree.pane.id)) scheduleRefresh()
        return {}
      case 'main-loop-edit':
        void warnDiffPanelOnce()
        if (!hasAutoOpened) {
          hasAutoOpened = true
          if (mayAutoOpen() && (await showDiff())) return { note: DIFF_NOTE }
        }
        return {}
      case 'show-doc': {
        const { path } = action
        if ((!docs.has(path) || action.force) && mayAutoOpen())
          await showDoc({ kind: 'file', path })
        if (!isMainLoop || docs.get(path) !== 'shown') return {}
        docs.set(path, 'told')
        return { note: planPaths.has(path) ? planNoteOf(path) : docNoteOf(path) }
      }
      case 'reload-doc':
        await doc.reload(action.path)
        bandState.noteDocReloaded(action.path, await isPaneShown(doc.pane.id))
        return {}
      case 'directive':
        return { text: await runDirective(action.directive) }
      case 'tasks': {
        const changed = tasksView.apply(action.tool, action.input, action.result)
        if (changed && !hasOpenedTasks && tasksView.hasTasks()) {
          hasOpenedTasks = true
          if (open.size === 0 && mayAutoOpen()) await show(tasksView)
        }
        return {}
      }
    }
  }

  /** Records `kind` against `text` for a later `resultKindOf`, and returns the pair as-is. */
  const resultOf = (kind: CommandKind, text: string): CommandResult => {
    resultKindByText.set(text, kind)
    return { kind, text }
  }

  async function toggle(view: View): Promise<CommandResult> {
    const name = `Raven ${view.pane.title.toLowerCase()}`
    if (open.has(view.pane.id) && (await isPaneShown(view.pane.id))) {
      await hide(view)
      return resultOf('hidden', `${name} hidden`)
    }
    const isShown = await showView(view)
    return isShown ? resultOf('shown', `${name} shown`) : resultOf('narrow', NARROW_TEXT)
  }

  const argumentHint = `[${[...views.map(view => view.subcommand), SEND].join('|')}]`

  /** Never rejects: a thrown failure becomes an `'error'` result like usage help does. */
  async function command(args: string): Promise<CommandResult> {
    try {
      await warnDiffPanelOnce()
      const word = args.trim() || diff.subcommand
      const view = views.find(each => each.subcommand === word)
      if (view) return toggle(view)
      if (word === SEND) {
        return (await sendReview())
          ? resultOf('shown', 'Review sent')
          : resultOf('hidden', 'No review comments to send')
      }
      return resultOf('error', `Usage: /raven ${argumentHint}`)
    } catch (error) {
      return resultOf('error', `Raven failed: ${String(error)}`)
    }
  }

  async function takePromptContext() {
    // A prompt can carry comments before any pane has ever loaded the review (the band's own
    // load path, reused here so both see the same `hasLoadedReview` guard).
    await bandState.ensureReviewLoaded()
    const known = diff.knownPaths()
    const toplevel = diff.toplevel()
    let existing: ReadonlySet<string> | null = null
    if (known !== null && toplevel !== null) {
      // Only the comments `known` doesn't already resolve need the existence check:
      // `existingPathsOf` batches all of them together (chunked, never one call per comment),
      // and this is skipped entirely when `known` is null (everything is already live) or
      // there is nothing left to check.
      const candidates = review
        .pending()
        .filter(comment => comment.section === undefined && !known.has(comment.path))
      if (candidates.length > 0) {
        const paths = [...new Set(candidates.map(comment => comment.path))]
        existing = await existingPathsOf(host.run, toplevel, paths).catch(
          loggedAs(host, 'checking comment file existence', null),
        )
      }
    }
    const taken = review.take(isLiveComment(known, existing))
    const text = reviewTextOf(taken)
    if (text === undefined) return undefined
    return { text, count: taken.length, ids: taken.map(comment => comment.id) }
  }

  return {
    argumentHint,
    command,
    afterTool: async event => {
      const texts: string[] = []
      const notes: string[] = []
      try {
        for (const action of actionsOf(event, triggers, planPaths)) {
          // A subagent's result is not where the main loop would read a note.
          const { text, note } = await runAction(action, event.agentId === undefined)
          if (text !== undefined) texts.push(text)
          if (note !== undefined) notes.push(note)
        }
      } catch (error) {
        host.debug(`raven: afterTool failed: ${String(error)}`)
      }
      return { text: texts.length > 0 ? texts.join('\n') : undefined, notes }
    },
    planNoted: async note => {
      planPaths.add(note.planFilePath)
      try {
        // No tool result carries these opens, so no note is made for them.
        for (const action of planActionsOf(note)) await runAction(action, false)
      } catch (error) {
        host.debug(`raven: planNoted failed: ${String(error)}`)
      }
    },
    runTool: async input => {
      const directive = directiveOf(input)
      if (!directive)
        throw new Error(`Invalid input for the Raven show tool: ${JSON.stringify(input)}`)
      return runDirective(await resolveDirective(directive))
    },
    takePromptContext,
    noteCarried: count => {
      host.toast(toastOfCarried(count, 'this prompt'))
    },
    takeAnswerContext: async () => {
      try {
        const carried = await takePromptContext()
        if (carried) host.toast(toastOfCarried(carried.count, 'your answer'))
        return carried?.text
      } catch (error) {
        host.debug(`raven: carrying the review on an answer failed: ${String(error)}`)
        return undefined
      }
    },
    restoreCarried: ids => {
      if (ids.length > 0) review.restore(ids)
    },
    turnCompleted: async turn => {
      diff.turnEnded()
      if (turn.reason === 'answer') await resolveSent()
    },
    // A throwing handler is logged, never rejected into the `ui.message` hook (which would fail the post).
    press: (paneId, id) => {
      try {
        return presses.dispatch(paneId, id)
      } catch (error) {
        host.debug(`raven: press handler "${id}" threw: ${String(error)}`)
        return true
      }
    },
    registerPress: (paneId, id, onPress) => presses.add(paneId, id, onPress),
    render: (paneId, kit) => {
      const view = views.find(each => each.pane.id === paneId)
      if (!view) return null
      // A reloaded module inherits open panes it never opened: drawing one proves it is open, and
      // its model starts empty until a refresh.
      if (!open.has(paneId)) {
        open.add(paneId)
        void view.refresh?.().catch(error => host.debug(`raven: refresh failed: ${String(error)}`))
      }
      if (view === doc) bandState.noteDocRendered()
      presses.begin(paneId)
      return paneFill(kit, settings.paneBackground, view.render(kit))
    },
    scroll: (paneId, by) => views.find(view => view.pane.id === paneId)?.scroll?.(by) ?? false,
    paneClosed: paneId => {
      open.delete(paneId)
      host.redraw()
    },
    noteViewport: columns => bandState.noteViewport(columns),
    // `begin` runs right before the band's synchronous registrations, after the band's awaits: a
    // render that draws nothing, or a newer one landing meanwhile, never wipes handlers it still needs.
    band: (kit, hasSurvey, requestId) =>
      bandState.band(kit, hasSurvey, () => presses.begin(requestId)),
    resultKindOf: text => resultKindByText.get(text) ?? 'info',
  }
}

