  edited: ReadonlySet<string>
  /**
   * Absolute paths an edit touched before a refresh had yet loaded the repository (so no
   * toplevel was known to make them relative); a later refresh resolves and folds them into
   * `edited`, or drops them if they turn out to lie outside the repository.
   */
  pendingEdited: ReadonlySet<string>
  /**
   * The absolute path to reveal once the refresh it is waiting on completes and lands against a
   * freshly computed stream; null when idle. Left set (not dropped) while a compose box is open,
   * so the jump still happens once the box closes and a later refresh runs.
   */
  followPath: string | null
  /** False once the person scrolls the stream this turn; a further edit then leaves the view put. */
  isFollowing: boolean
  /**
   * Which review-comment paths are confirmed gone from the working tree: a property of the
   * repository, not of the selected source, so it is checked over every non-doc comment's path
   * regardless of which are currently orphaned. Empty until a check actually names one gone, so a
   * path never checked (or one a failed check couldn't confirm) never draws "file gone": fail
   * open, same as everywhere else this check feeds.
   */
  gonePaths: ReadonlySet<string>
}

const EMPTY_EDITED: ReadonlySet<string> = new Set()

/** What the diff view asks of the controller. */
export type DiffActions = {
  /** Submits the pending review to Claude. */
  send: () => void
  /** Fills the prompt with the pending review so the person can edit it before sending. */
  editAndSend: () => void
  /** Gives the keyboard to the element drawn under `key`. */
  focus: (key: string) => void
}

export type DiffView = View & {
  refresh: () => Promise<void>
  /** Selects the file at an absolute path, when it is among the changes. */
  reveal: (path: string) => void
  /** Marks `absolutePath` edited this turn; while following, the next refresh reveals it. */
  noteEdited: (absolutePath: string) => void
  /** Clears this turn's edited marks and resumes following, for the controller to call per turn. */
  turnEnded: () => void
  /**
   * The paths of the last loaded git-source file list (each file's current path, plus a renamed
   * file's `oldPath`); `null` before the first load, when the repository is unknown, or while a
   * turn (read-only) source is selected: a turn's file list is not the live git diff.
   */
  knownPaths: () => ReadonlySet<string> | null
  /** The current repository's toplevel; null whenever no repository has loaded. */
  toplevel: () => string | null
}

/** What the diff view takes from the person's settings. */
export type DiffOptions = {
  /** The body width, in columns, at which the diff goes side by side unless forced. */
  splitColumns: number
}

/**
 * A wholly added or deleted file's visible lines as numbered source, its "No newline" marker dim
 * beneath. A view over the `Code` cap is cut into numbered pieces (`wholePiecesOf`).
 */
function wholeCodeOf(kit: Kit, path: string, whole: WholeSource): RenderElement {
  const { Box, Code, Text } = kit.ui
  const pieces = wholePiecesOf(whole)
  return (
    <Box flexDirection="column" overflow="hidden">
      {whole.count > 0
        ? pieces.map(piece => (
            <Code
              key={`whole:${piece.startLine}`}
              source={piece.source}
              format="source"
              startLine={piece.startLine}
              path={path}
              wrap="truncate-end"
            />
          ))
        : null}
      {whole.tail.map((line, index) => (
        <Text key={`tail:${index}`} dimColor wrap="truncate-end">
          {line}
        </Text>
      ))}
    </Box>
  )
}

export function createDiffView(
  host: Host,
  review: Review,
  actions: DiffActions,
  now: () => number,
  options: DiffOptions = { splitColumns: DEFAULT_SETTINGS.splitColumns },
): DiffView {
  let model: Model = {
    repository: null,
    isLoaded: false,
    selected: null,
    hunks: new Map(),
    composing: null,
    composingLine: null,
    composingText: '',
    top: 0,
    stagedHunks: new Map(),
    confirming: null,
    pendingReveal: null,
    edited: EMPTY_EDITED,
    pendingEdited: EMPTY_EDITED,
    followPath: null,
    isFollowing: true,
    gonePaths: EMPTY_GONE_PATHS,
  }

  const sourceController = createSourceController(host)
  const splitMode = createSplitMode(host, options.splitColumns)

  // The body rows and the title rows/content-row count of the most recent render computed, so
  // `scroll` and `select` (which have no kit) can clamp/jump without recomputing them.
  let lastBodyRows = 0
  let lastTitleRows: ReadonlyMap<string, number> = new Map()
  let lastContentRows = 0
  let lastBlocks: readonly Block<BodyItem>[] = []

  // The last streamOf() result, valid while its inputs are reference-equal to these.
  let cache: {
    files: readonly ChangedFile[]
    hunks: ReadonlyMap<string, readonly Hunk[]>
    comments: Comments
    composing: Anchor | null
    composeKey: string
    readOnly: boolean
    capabilities: Capabilities
    isLoaded: boolean
    gonePaths: ReadonlySet<string>
    width: number
    cardStyle: Style['cardStyle']
    isSplit: boolean
    stream: Stream
  } | null = null

  /** The files the current source shows: the repository's, or one turn's edited files. */
  function filesOf(): readonly ChangedFile[] {
    return sourceController.files(model.repository)
  }

  // Any action but a second "clear"/"revert" press drops the armed confirm, so `patch` overrides
  // it only when the caller means to set one.
  const update = (patch: Partial<Model>) => {
    model = { ...model, confirming: null, ...patch }
    host.redraw()
  }

  /** Drops the armed confirm without any other change; the intent-bearing name for a bare `update({})`. */
  const resetConfirm = () => update({})

  const isArmed = (key: string) => model.confirming === key
  const arm = (key: string) => update({ confirming: key })

  // Bumped by each refresh, so a slow read that lands after a newer one is dropped.
  let generation = 0

  /** Drops staged marks for headers that no longer appear in `file`'s current hunks. */
  function prunedStaged(
    path: string,
    hunks: readonly Hunk[],
  ): ReadonlyMap<string, ReadonlySet<string>> {
    const staged = model.stagedHunks.get(path)
    if (!staged || staged.size === 0) return model.stagedHunks
    const headers = new Set(hunks.map(hunk => hunk.header))
    const kept = new Set([...staged].filter(header => headers.has(header)))
    return kept.size === staged.size
      ? model.stagedHunks
      : new Map(model.stagedHunks).set(path, kept)
  }

  const NO_HUNKS = { hunks: [] as Hunk[], isTruncated: false }

  /** A file's hunks against the current base; none (logged) when git fails. */
  const readHunks = (file: ChangedFile) =>
    loadHunks(host.run, file, sourceController.base()).catch(
      loggedAs(host, 'loading hunks', NO_HUNKS),
    )

  /** The model patch that seats `hunks` as `path`'s, keeping only staged marks still present. */
  const withHunks = (path: string, hunks: readonly Hunk[]) => ({
    hunks: new Map(model.hunks).set(path, hunks),
    stagedHunks: prunedStaged(path, hunks),
  })

  /**
   * `prunedStaged` over every path a bulk reload read, for the one `update` a `refresh` makes;
   * also drops any path no longer among `files` at all (deleted, reverted, renamed away).
   */
  function prunedStagedAll(
    files: readonly ChangedFile[],
    hunks: ReadonlyMap<string, readonly Hunk[]>,
  ): ReadonlyMap<string, ReadonlySet<string>> {
    let staged = model.stagedHunks
    if (staged.size === 0) return staged

    const live = new Set(files.map(file => file.path))
    if ([...staged.keys()].some(path => !live.has(path))) {
      staged = new Map([...staged].filter(([path]) => live.has(path)))
    }

    for (const [path, pathHunks] of hunks) {
      const current = staged.get(path)
      if (!current || current.size === 0) continue
      const headers = new Set(pathHunks.map(hunk => hunk.header))
      const kept = new Set([...current].filter(header => headers.has(header)))
      if (kept.size !== current.size) staged = new Map(staged).set(path, kept)
    }
    return staged
  }

  async function refresh() {
    await sourceController.resolveStoredSource()
    const started = ++generation
    const read = () =>
      loadChanges(host.run, sourceController.base()).catch(loggedAs(host, 'loading changes', null))
    const baseRead = refOf(sourceController.base())
    let repository = await read()
    if (started !== generation) return

    await sourceController.refresh(repository)
    await splitMode.resolveStored(repository?.toplevel ?? null)
    // Resolving the sources can move the base (the branch point is known only now): read again.
    if (refOf(sourceController.base()) !== baseRead) repository = await read()
    if (started !== generation) return

    const files = sourceController.files(repository)
    const isKept = files.some(file => file.path === model.selected)

    // A turn source's hunks come from the controller's own `turnHunks`, read straight off it;
    // only a git source needs this bulk read.
    let hunks: ReadonlyMap<string, readonly Hunk[]> = new Map()
    let stagedHunks = model.stagedHunks
    if (!sourceController.isReadOnly()) {
      const loaded = await loadAllHunks(host.run, files, sourceController.base()).catch(
        loggedAs(host, 'loading hunks', { byPath: new Map(), truncatedPath: null }),
      )
      if (started !== generation) return
      hunks = loaded.byPath
      // A header collides easily (e.g. `@@ -1,2 +1,2 @@`); drop a path's stale staged marks
      // rather than risk a new hunk reading as already staged.
      stagedHunks = prunedStagedAll(files, hunks)
      if (loaded.truncatedPath !== null)
        host.toast(`${loaded.truncatedPath}: diff too large, its last hunk is not shown`)
    }

    // An edit noted before this refresh learned the toplevel (e.g. the session's very first edit,
    // ahead of the auto-open refresh that first loads the repository) sat in `pendingEdited`
    // absolute; resolve it against the toplevel this refresh now knows, same as `relativeOf` does
    // for a fresh edit. While the toplevel is still unknown (no repository yet), every entry stays
    // pending; once it is known, one that turns out to lie outside the repository is dropped.
    const toplevel = repository?.toplevel
    const stillPending: string[] = []
    const newlyResolved: string[] = []
    for (const abs of model.pendingEdited) {
      if (toplevel === undefined) stillPending.push(abs)
      else if (abs.startsWith(`${toplevel}/`)) newlyResolved.push(abs.slice(toplevel.length + 1))
    }
    const edited =
      newlyResolved.length === 0 ? model.edited : new Set([...model.edited, ...newlyResolved])
    const pendingEdited =
      stillPending.length === model.pendingEdited.size ? model.pendingEdited : new Set(stillPending)

    update({
      repository,
      isLoaded: true,
      hunks,
      stagedHunks,
      selected: isKept ? model.selected : (files[0]?.path ?? null),
      edited,
      pendingEdited,
    })

    if (repository) await review.load(repository.toplevel)
    if (started !== generation) return

    // Existence is a property of the repository, not of which source happens to be selected, so
    // every non-doc comment's path is checked here (not just the ones currently orphaned)
    // sparing `selectSource` (a mere source switch) from ever needing its own check.
    const commentPaths = [
      ...new Set(
        review
          .comments()
          .filter(comment => comment.section === undefined)
          .map(comment => comment.path),
      ),
    ]
    let gonePaths: ReadonlySet<string> = EMPTY_GONE_PATHS
    if (repository && commentPaths.length > 0) {
      const existing = await existingPathsOf(host.run, repository.toplevel, commentPaths).catch(
        loggedAs(host, 'checking comment file existence', null),
      )
      // `existing === null` is a failed check, not "nothing exists": leave `gonePaths` empty
      // (fail open) rather than mark every candidate gone.
      if (existing !== null) gonePaths = new Set(commentPaths.filter(path => !existing.has(path)))
    }
    if (started !== generation) return
    update({ gonePaths })

    followIfDue()
  }

  /**
   * Selects `path` and scrolls its heading to the top of the stream; no reload. Always jumps,
   * even when `path` is already selected: pressing the row of the file the scroll bar's ❯
   * already tracks is exactly how the stream's top is recovered after scrolling away from it.
   * The person's own navigation (a file-list press, the ↓/↑ buttons): turns follow off for the
   * rest of the turn, same as a scroll. A programmatic jump (`reveal`) does its own update
   * instead, so a directive or a follow-driven jump never trips this.
   */
  function select(path: string) {
    update({
      selected: path,
      composing: null,
      top: lastTitleRows.get(path) ?? model.top,
      pendingReveal: null,
      isFollowing: false,
      followPath: null,
    })
  }

  /** Moves the selection `by` files (1 next, -1 previous); the ↓/↑ buttons. */
  function stepSelection(by: number) {
    const files = filesOf()
    if (files.length === 0) return
    const from = files.findIndex(file => file.path === model.selected)
    const file = files[stepFileIndexOf(files.length, from, by)]
    if (file) select(file.path)
  }

  /** Switches the source; a turn's files are already known, a git base triggers a reload. */
  function selectSource(value: string) {
    sourceController.select(value)
    update({ top: 0, composing: null })

    if (sourceController.isReadOnly()) {
      const files = filesOf()
      update({ selected: files[0]?.path ?? null })
      return
    }

    void refresh()
  }

  // Whether the last render drew a `Client` strip: its note pill is then no keyed element to focus.
  let isClient = false

  function startComposing(anchor: Anchor) {
    update({ composing: anchor, composingLine: null, composingText: '' })
    actions.focus(inputKeyOf(anchor))
  }

  /** Closes the compose box and hands the keyboard back to its anchor's comment button. */
  function stopComposing(anchor: Anchor) {
    update({ composing: null, composingLine: null, composingText: '' })
    if (!isClient) actions.focus(commentButtonKeyOf(anchor))
  }

  function submitComment(anchor: Anchor, text: string, isSplit = false) {
    if (text.trim() !== '') {
      const line = effectiveLineOf(model.composingLine, isSplit)
      review.add(line ? { ...anchor, line, text: text.trim() } : { ...anchor, text: text.trim() })
    }
    stopComposing(anchor)
  }

  function pressClear() {
    if (isArmed('clear')) {
      resetConfirm()
      review.clear()
    } else {
      arm('clear')
    }
  }

  /**
   * Runs `git apply` for one hunk's patch; marks it staged on success, reloads hunks either way.
   * Re-reads the file's current hunks first: `hunk` was captured at the last render, and the
   * working tree may have moved under it since (an edit, a stage/revert from elsewhere). Applying
   * a patch built from a header that no longer matches the file risks silently touching the wrong
   * lines, so an exact header+text match is required before `git apply` ever runs.
   */
  async function applyHunk(file: ChangedFile, hunk: Hunk, mode: 'stage' | 'revert') {
    const { hunks: current } = await readHunks(file)
    const stillPresent = current.some(
      candidate => candidate.header === hunk.header && candidate.text === hunk.text,
    )
    if (!stillPresent) {
      host.toast('The hunk changed. Refreshed, try again')
      update(withHunks(file.path, current))
      return
    }
    const result = await applyPatch(host.run, patchOf(file, hunk), mode)
    if (!result.ok) {
      host.toast(
        `Raven: git ${mode === 'stage' ? 'apply --cached' : 'apply -R'} failed: ${result.error ?? 'unknown error'}`,
      )
      return
    }
    if (mode === 'stage') {
      const current = model.stagedHunks.get(file.path) ?? new Set<string>()
      update({
        stagedHunks: new Map(model.stagedHunks).set(file.path, new Set(current).add(hunk.header)),
      })
    }
    await refresh()
  }

  /** First press asks for confirmation; a second press on the same hunk reverts it. */
  function pressRevert(file: ChangedFile, hunk: Hunk, anchor: Anchor) {
    const key = anchorKeyOf(anchor)
    if (isArmed(key)) {
      resetConfirm()
      void applyHunk(file, hunk, 'revert')
    } else {
      arm(key)
    }
  }

  /** Every changed file's blocks in one stream, cached while its inputs are unchanged. */
  function streamFor(
    capabilities: Capabilities,
    width: number,
    style: Style,
    isSplit = false,
  ): Stream {
    const files = filesOf()
    const source = sourceController.source()
    const readOnly = sourceController.isReadOnly()
    const comments = review.comments()
    // The compose box's height follows the preview rows of the typed text; the stream re-sizes
    // only when their count changes.
    const composeKey = model.composing
      ? String(
          composePreviewCountOf(
            model.composingText,
            model.composing.hunk !== undefined && capabilities.canPick,
            composeInnerWidthOf(width),
          ),
        )
      : ''

    if (
      cache &&
      cache.files === files &&
      cache.hunks === model.hunks &&
      cache.comments === comments &&
      cache.composing === model.composing &&
      cache.composeKey === composeKey &&
      cache.readOnly === readOnly &&
      cache.capabilities.canType === capabilities.canType &&
      cache.capabilities.canPick === capabilities.canPick &&
      cache.isLoaded === model.isLoaded &&
      cache.gonePaths === model.gonePaths &&
      cache.width === width &&
      cache.cardStyle === style.cardStyle &&
      cache.isSplit === isSplit
    ) {
      return cache.stream
    }

    const stream = streamOf(
      files,
      file => selectedHunksOf(source, sourceController.hunksFor(file), model.hunks.get(file.path)),
      comments,
      model.composing,
      {
        readOnly,
        capabilities,
        width,
        style,
        split: isSplit,
        composeText: model.composingText,
        // Once the repository has loaded, a file absent from `model.hunks` was genuinely not
        // read (an untracked file past the cap, or a failed `git diff`), not still loading.
        unreadText: model.isLoaded ? 'Not read' : undefined,
      },
      model.gonePaths,
    )
    cache = {
      files,
      hunks: model.hunks,
      comments,
      composing: model.composing,
      composeKey,
      readOnly,
      capabilities,
      isLoaded: model.isLoaded,
      gonePaths: model.gonePaths,
      width,
      cardStyle: style.cardStyle,
      isSplit,
      stream,
    }
    return stream
  }

  /** A note's card; its lines were wrapped when it was sized. */
  function noteRowOf(kit: Kit, item: Extract<BodyItem, { kind: 'note' }>): RenderElement {
    return note(kit, item.comment, item.lines, now(), id => review.remove(id), review.resend)
  }

  /** A file's title: icon, bold path, status mark, counts, then the inline `<note glyph> note` chip two columns after. */
  function titleRowOf(
    kit: Kit,
    item: Extract<BodyItem, { kind: 'title' }>,
    color: string,
    style: Style,
  ): RenderElement {
    const { Box, Text } = kit.ui
    const mark = statusMarkOf(item.file.status)
    const icon = iconOf(item.file.path)
    const tag = fileTagOf(item.file.status)
    const title = (
      <Text wrap="truncate-end">
        <Text color={icon.color}>{icon.glyph}</Text>
        <Text bold>{`${ICON_GAP}${item.file.path}`}</Text>
        <Text color={mark.color}>{`  ${mark.glyph}`}</Text>
        {item.file.adds > 0 ? <Text color={COLORS.added}>{` +${item.file.adds}`}</Text> : null}
        {item.file.dels > 0 ? <Text color={COLORS.removed}>{` −${item.file.dels}`}</Text> : null}
        {tag ? <Text dimColor>{`  ${tag}`}</Text> : null}
      </Text>
    )
    const anchor: Anchor = { path: item.file.path }
    const titleKey = `title-row:${item.file.path}`
    let chips: RenderElement | undefined
    if (item.canNote) {
      const chip = noteChip(anchor, startComposing)
      // The same HEADER_MIN the hunk label row reserves for its own label, so the title's single
      // note pill shrinks to its bare icon under the same pressure, the path (which already
      // truncates on its own) giving way first.
      const mode = chipsFit([chip], ruleRoomFor(kit.columns, HEADER_MIN))
      chips = pillRow(kit, [chip], mode, titleKey)
    }
    return <Box key={titleKey}>{cardTitle(kit, style, { color, title, chips })}</Box>
  }

  /**
   * One fixed row's element, by its payload kind: a `gap` draws one blank row, between files.
   * `contentWidth` is the row's room beside the file's left rail (`contentWidthOf`), for whatever
   * here measures text instead of `kit.columns`; the rail itself is drawn by the caller,
   * `placedRowOf`.
   */
  function bodyRowOf(
    kit: Kit,
    item: BodyItem,
    file: ChangedFile,
    contentWidth: number,
    color: string,
  ): RenderElement {
    const { Box, Text } = kit.ui
    switch (item.kind) {
      case 'close':
        return frameBottom(kit, kit.style, color) ?? <Box />
      case 'title':
        return titleRowOf(kit, item, color, kit.style)
      case 'status':
        return (
          <Text dimColor wrap="truncate-end">
            {item.text}
          </Text>
        )
      case 'gap':
      case 'blank':
        return <Text> </Text>
      case 'outdated-title':
        return outdatedHeading(kit)
      // The orphans group's own rows never pass through here: `placedRowOf` dispatches any block
      // flagged `orphan` to `orphanRowOf` before a file is ever looked up for `bodyRowOf`.
      case 'orphans-title':
      case 'orphan-path':
        return <Box />
      case 'addressed':
        return addressedRow(kit, item.anchor, item.count)
      case 'note':
        return noteRowOf(kit, item)
      case 'comment-box':
        return commentBox(kit, {
          anchor: item.anchor,
          inputKey: inputKeyOf(item.anchor),
          hunk: item.hunk,
          hasPicker: item.hasPicker,
          // The stream caches on the preview's row count, so its lines come from the live text here
          // (same text, width and picker, so the same count the block was sized with).
          preview: composePreviewLinesOf(
            model.composingText,
            item.hasPicker,
            composeInnerWidthOf(contentWidth),
          ),
          isSplit: item.isSplit,
          draft: model.composingText,
          line: effectiveLineOf(model.composingLine, item.isSplit ?? false),
          columns: contentWidth,
          onInput: text => {
            if (text !== model.composingText) update({ composingText: text })
          },
          onLineChange: line => update({ composingLine: line }),
          onSubmit: text => submitComment(item.anchor, text, item.isSplit ?? false),
          onCancel: () => stopComposing(item.anchor),
        })
      case 'hunk-header':
        return (
          <Box flexDirection="row" overflow="hidden" flexWrap="nowrap">
            <Box flexGrow={1} overflow="hidden">
              {hunkToolbar(kit, {
                anchor: item.anchor,
                path: file.path,
                hunk: item.hunk,
                canNote: item.canNote,
                isReadOnly: item.isReadOnly,
                isStaged: (model.stagedHunks.get(file.path) ?? EMPTY_STAGED).has(item.hunk.header),
                confirmingRevert: isArmed(anchorKeyOf(item.anchor)),
                columns: contentWidth,
                onStartNote: startComposing,
                onStage: () => void applyHunk(file, item.hunk, 'stage'),
                onRevert: () => pressRevert(file, item.hunk, item.anchor),
              })}
            </Box>
          </Box>
        )
    }
  }

  /**
   * A fixed block whose top `from` rows scrolled out of the window: the block drawn whole, shifted
   * up by `from` inside a box only `to - from` rows tall that clips it, so the visible rows of a
   * card still show and nothing below moves.
   */
  function clippedOf(
    kit: Kit,
    key: string,
    element: RenderElement,
    placed: Placed<BodyItem>,
  ): RenderElement {
    if (placed.from === 0) return element
    const { Box } = kit.ui
    return (
      <Box key={key} height={placed.to - placed.from} overflow="hidden">
        <Box position="absolute" top={-placed.from} left={0} right={0}>
          {element}
        </Box>
      </Box>
    )
  }

  /**
   * One block of the trailing orphans group: no `ChangedFile` backs these rows, so they never go
   * through `bodyRowOf`/`placedRowOf`'s file-rail logic; no rail is drawn (the group is not a card). Only the item kinds `orphanBlocksOf` ever emits reach here.
   */
  function orphanRowOf(kit: Kit, placed: Placed<BodyItem>): RenderElement {
    const { Box, Text } = kit.ui
    const { block } = placed
    if (block.kind !== 'fixed') return <Box key={block.key} />
    const { item } = block

    let content: RenderElement
    switch (item.kind) {
      case 'orphans-title':
        content = orphansTitle(kit)
        break
      case 'orphan-path':
        content = orphanPathRow(kit, item.path, item.isGone)
        break
      case 'addressed':
        content = addressedRow(kit, item.anchor, item.count)
        break
      case 'note':
        content = noteRowOf(kit, item)
        break
      case 'blank':
        content = <Text> </Text>
        break
      default:
        content = <Box />
    }

    // The trailing group is not a file's card: no rail, indented to line up with the cards' text.
    const indent = groupCellsOf(kit.style)
    return clippedOf(
      kit,
      block.key,
      <Box key={block.key} flexDirection="row" overflow="hidden" flexWrap="nowrap">
        {indent > 0 ? <Text>{' '.repeat(indent)}</Text> : null}
        <Box flexGrow={1} overflow="hidden">
          {content}
        </Box>
      </Box>,
      placed,
    )
  }

  /**
   * A placed block's element; the file it belongs to is found by its key's `path#...` prefix.
   * Every body row of a file's card draws behind the style's mark (`groupRows`): `▌ ` in the
   * file's status colour under `bar`, nothing under `none`, `│ ` and ` │` under a frame. A hunk
   * `Code` slice spans several terminal rows at once, so its rail is that many rows tall. The
   * title, the frame's closing row and the blank row between files span the whole width and carry
   * no rail. D10 point 2: the file being edited this turn draws its rail (or frame) in the accent
   * instead, so the live feed is visible from across the room. The trailing orphans group
   * (blocks flagged `orphan`) has no file at all, so it is dispatched to `orphanRowOf` first.
   */
  function placedRowOf(
    kit: Kit,
    placed: Placed<BodyItem>,
    filesByPath: ReadonlyMap<string, ChangedFile>,
  ): RenderElement {
    const { Box, Code, Text } = kit.ui
    const { style } = kit
    const { block } = placed
    if (block.kind === 'fixed' && block.orphan) return orphanRowOf(kit, placed)
    const path = block.card ?? sepPathOf(block.key) ?? ''
    const file = filesByPath.get(path)
    if (!file) return <Box key={block.key} />

    const contentWidth = contentWidthOf(kit.columns, style)
    const railColor = model.edited.has(file.path) ? COLORS.accent : statusMarkOf(file.status).color

    if (block.kind === 'hunk') {
      // A segment ending at a commented line draws its ◆ only once that last row is in view.
      const isMarked = block.mark !== undefined && placed.to === rowsOf(block)
      const mark = isMarked && block.mark ? NOTE_STATE_COLORS[block.mark] : undefined
      const bodyOf = (): RenderElement => {
        if (block.split) {
          // Windowed by split-row index, so there is no unified slice to take.
          return splitHunk(kit, {
            key: `split:${block.key}`,
            split: block.split,
            from: placed.from,
            to: placed.to,
            width: contentWidth,
          })
        }
        const sliced = sliceHunk(block.hunk, placed.from, placed.to)
        const whole = block.whole ? wholeSourceOf(sliced, block.whole) : null
        return whole ? (
          wholeCodeOf(kit, file.path, whole)
        ) : (
          <Code source={sliced.text} format="diff" path={file.path} wrap="truncate-end" />
        )
      }
      return (
        <Box key={block.key}>
          {groupRows(kit, style, {
            color: railColor,
            rows: placed.to - placed.from,
            mark,
            children: bodyOf(),
          })}
        </Box>
      )
    }

    const { item } = block
    // The blank row under a title carries no rail outside a frame: the rail starts at the label.
    const isOpenTitleGap = block.key.endsWith(`#${TITLE_GAP_KEY}`) && !style.frame
    if (isOpenTitleGap || item.kind === 'gap' || item.kind === 'title' || item.kind === 'close') {
      return clippedOf(
        kit,
        block.key,
        <Box key={block.key}>{bodyRowOf(kit, item, file, kit.columns, railColor)}</Box>,
        placed,
      )
    }

    // The compose box is the one frame: under bar and none the rail does not run through its rows;
    // it sits on the code's left edge instead (inside the rails under a frame style).
    if (item.kind === 'comment-box' && !style.frame) {
      const indent = groupCellsOf(style)
      return clippedOf(
        kit,
        block.key,
        <Box key={block.key} flexDirection="row" overflow="hidden" flexWrap="nowrap">
          {indent > 0 ? <Text>{' '.repeat(indent)}</Text> : null}
          <Box flexGrow={1} overflow="hidden">
            {bodyRowOf(kit, item, file, contentWidth, railColor)}
          </Box>
        </Box>,
        placed,
      )
    }

    return clippedOf(
      kit,
      block.key,
      <Box key={block.key}>
        {groupRows(kit, style, {
          color: railColor,
          rows: block.rows,
          children: bodyRowOf(kit, item, file, contentWidth, railColor),
        })}
      </Box>,
      placed,
    )
  }

  /**
   * The pinned title: the scrolled card's title as the body's first row, drawn as the title line
   * alone (no rule under `none`) under its own key, so `<path>#title` is still absent deep in a
   * scroll. Its chips are the real title's (same keys and press ids): the real title is not placed
   * while this is. Frame styles draw the title line as the card kit does.
   */
  function pinnedRowOf(
    kit: Kit,
    block: FixedBlock<BodyItem>,
    filesByPath: ReadonlyMap<string, ChangedFile>,
  ): RenderElement {
    const { Box } = kit.ui
    const path = block.card ?? ''
    const file = filesByPath.get(path)
    const { item } = block
    if (!file || item.kind !== 'title') return <Box key={`${path}#pinned`} />
    const color = model.edited.has(file.path) ? COLORS.accent : statusMarkOf(file.status).color
    return (
      <Box key={`${path}#pinned`}>
        {titleRowOf(kit, item, color, { ...kit.style, titleRule: false })}
      </Box>
    )
  }

  /** Whether the diff draws side by side in a pane `columns` wide whose body is `bodyWidth` wide. */
  const isSplitAt = (columns: number, bodyWidth: number) =>
    splitMode.canSplit(bodyWidth) && splitMode.isSplit(columns)

  /**
   * Flips the layout and keeps the person where they were: the stream's rows change with it, so
   * `top` is re-anchored in the stream the new layout draws: to the open compose box (its Input
   * must stay mounted), else to the selected file's title, else to the title of the file that was
   * at `top`. A picked line survives unless the new layout does not offer it (an old-side line in
   * split).
   */
  function toggleSplit(kit: Kit, bodyWidth: number) {
    if (!splitMode.canSplit(bodyWidth)) return
    // The file the old layout shows at `top`, read before the layout flips: with no compose box and
    // no selected file in the stream, the new layout keeps the person at that file's title.
    const heldFile = fileAtRow(lastTitleRows, model.top)
    splitMode.toggle(kit.columns)
    const isSplit = isSplitAt(kit.columns, bodyWidth)
    const stream = streamFor(kit.capabilities, bodyWidth, kit.style, isSplit)
    const boxRow = model.composing
      ? rowOfKey(stream.blocks, `${model.composing.path}#${commentBoxKeyOf(model.composing)}`)
      : null
    const titleRow = model.selected === null ? undefined : stream.titleRows.get(model.selected)
    const heldRow = heldFile === null ? undefined : stream.titleRows.get(heldFile)
    const top = boxRow ?? titleRow ?? heldRow ?? model.top
    update({
      top,
      selected: fileAtRow(stream.titleRows, top) ?? model.selected,
      composingLine: effectiveLineOf(model.composingLine, isSplit),
    })
  }

  function render(kit: Kit): RenderElement {
    const { Box, Text } = kit.ui
    isClient = kit.capabilities.canClient
    const { repository } = model
    const isReadOnly = sourceController.isReadOnly()

    if (!model.isLoaded) return <Text dimColor>Reading the repository…</Text>
    if (!isReadOnly && !repository)
      return emptyState(
        kit,
        EMPTY_ICONS.repo,
        'Not a git repository. Open Raven in a repo to review changes',
      )

    const files = filesOf()
    // The body and the header chip decide split from the same widths. The threshold reads the
    // pane's columns; the minimum reads the body's, which is what the renderer lays two sides in.
    const bodyWidth = contentWidthOf(kit.columns, kit.style)
    const isSplit = isSplitAt(kit.columns, bodyWidth)
    const stream = streamFor(kit.capabilities, bodyWidth, kit.style, isSplit)
    // A comment whose file left the diff still has to draw somewhere (R32 part 2's orphans
    // group): the empty-state text only wins when the stream is truly empty, not just the file
    // list.
    if (files.length === 0 && stream.blocks.length === 0) {
      return emptyState(
        kit,
        EMPTY_ICONS.changes,
        isReadOnly
          ? 'This turn edited no files'
          : "No changes yet. Raven shows Claude's edits here as they land",
      )
    }

    lastTitleRows = stream.titleRows
    lastContentRows = stream.contentRows
    lastBlocks = stream.blocks

    // A `reveal` for a file not yet in the last stream (a refresh still in flight when it was
    // called) lands here once `streamFor` finally places it.
    const pendingRow =
      model.pendingReveal !== null ? stream.titleRows.get(model.pendingReveal) : undefined
    if (pendingRow !== undefined) model = { ...model, top: pendingRow, pendingReveal: null }

    const headerProps: HeaderProps = {
      files,
      edited: model.edited,
      pending: review.pending().length,
      confirmingClear: isArmed('clear'),
      sourceValue: sourceValueOf(sourceController.source()),
      sourceOptions: sourceController.options(),
      onSourceChange: selectSource,
      onRefresh: () => void refresh(),
      isSplit,
      canSplit: splitMode.canSplit(bodyWidth),
      onToggleSplit: () => toggleSplit(kit, bodyWidth),
      onSend: () => {
        resetConfirm()
        actions.send()
      },
      onEditSend: () => {
        resetConfirm()
        actions.editAndSend()
      },
      onPrevious: () => stepSelection(-1),
      onNext: () => stepSelection(1),
      onClear: pressClear,
    }
    const headerPlan = headerPlanFor(kit, headerProps)
    const bodyRows = Math.max(0, kit.rows - fixedRowsOf(files.length, MAX_ROWS, headerPlan.rows))
    lastBodyRows = bodyRows
    const top = clampTop(model.top, stream.contentRows, bodyRows, stream.blocks)
    if (top !== model.top) model = { ...model, top }

    const view = viewOf(stream.blocks, top, bodyRows)
    const filesByPath = new Map(files.map(file => [file.path, file]))

    return (
      <Box flexDirection="column">
        {header(kit, headerProps, headerPlan)}
        {fileList(kit, { files, selected: model.selected, edited: model.edited, onSelect: select })}
        {/* One short of the full width so the rule never wraps onto a row of its own. */}
        <Text dimColor>{'─'.repeat(Math.max(1, kit.columns - 1))}</Text>
        {view.pinned ? pinnedRowOf(kit, view.pinned, filesByPath) : null}
        {view.placed.map(p => placedRowOf(kit, p, filesByPath))}
      </Box>
    )
  }

  function scroll(by: number): boolean {
    // Not `filesOf().length === 0`: a zero-file diff can still scroll an orphans-only stream.
    if (lastContentRows === 0) return false
    const bodyRows = lastBodyRows
    const size = Math.abs(by)
    // A wheel tick or arrow asks for a row or two; scale it to a readable step, as the terminal's
    // own scrollable views do. A page or Home/End key already asks for a step this size or more.
    const step = size >= bodyRows ? size : size * WHEEL_ROWS
    const top = clampTop(model.top + Math.sign(by) * step, lastContentRows, bodyRows, lastBlocks)
    if (top !== model.top) {
      update({
        top,
        selected: fileAtRow(lastTitleRows, top) ?? model.selected,
        isFollowing: false,
        followPath: null,
        pendingReveal: null,
      })
    } else if (model.isFollowing) {
      update({ isFollowing: false, followPath: null, pendingReveal: null })
    }
    return true
  }

  /** `abs`, relative to the repository's toplevel; null when the toplevel is unknown or `abs` lies outside it. */
  function relativeOf(abs: string): string | null {
    const toplevel = model.repository?.toplevel
    return toplevel && abs.startsWith(`${toplevel}/`) ? abs.slice(toplevel.length + 1) : null
  }

  /**
   * Selects the file at an absolute path, when it is among the changes. When it isn't yet in the
   * last render's title rows (a refresh still in flight), the jump is deferred to `render` via
   * `pendingReveal` rather than left at the view's current `top`. A programmatic jump (a `diff`
   * directive naming a path): never touches follow, unlike `select`, which is the person's own
   * navigation.
   */
  function reveal(path: string) {
    const relative = relativeOf(path)
    if (relative === null) return
    if (lastTitleRows.has(relative)) {
      update({
        selected: relative,
        composing: null,
        top: lastTitleRows.get(relative) ?? model.top,
        pendingReveal: null,
      })
    } else {
      update({ selected: relative, composing: null, pendingReveal: relative })
    }
  }

  /**
   * Applies `model.followPath`, once a refresh completes, as a `pendingReveal` rather than an
   * immediate `select`, unlike `reveal`, so the jump always lands against the stream `render`
   * computes fresh this time, never a possibly-stale `lastTitleRows` from before this refresh.
   * Only while still following (no person scroll this turn dropped it already); a compose box
   * open keeps the target rather than applying or dropping it, so the jump still happens once the
   * box closes and a later refresh runs.
   */
  function followIfDue() {
    if (!model.isFollowing || model.followPath === null) return
    const relative = relativeOf(model.followPath)
    if (relative === null) {
      update({ followPath: null })
    } else if (model.composing === null) {
      update({ selected: relative, composing: null, pendingReveal: relative, followPath: null })
    }
  }

  /**
   * Marks `abs` edited this turn; while still following (no person scroll this turn), it becomes
   * the next refresh's follow target, replacing whichever earlier edit this turn was following.
   * Resolved to a path relative to the repository when the toplevel is already known; otherwise
   * queued in `pendingEdited` absolute, for `refresh` to resolve once it learns the toplevel (the
   * session's very first edit can land before the auto-open refresh that first loads it).
   */
  function noteEdited(abs: string) {
    const relative = relativeOf(abs)
    const followPath = model.isFollowing ? abs : model.followPath
    if (relative === null) {
      update({ pendingEdited: new Set(model.pendingEdited).add(abs), followPath })
    } else {
      update({ edited: new Set(model.edited).add(relative), followPath })
    }
  }

  /** Clears this turn's edited marks and resumes following, for the next turn. */
  function turnEnded() {
    update({
      edited: EMPTY_EDITED,
      pendingEdited: EMPTY_EDITED,
      followPath: null,
      isFollowing: true,
    })
  }

  function knownPaths(): ReadonlySet<string> | null {
    if (!model.isLoaded || !model.repository || sourceController.isReadOnly()) return null
    const paths = new Set<string>()
    for (const file of model.repository.files) {
      paths.add(file.path)
      if (file.oldPath !== undefined) paths.add(file.oldPath)
    }
    return paths
  }

  return {
    pane: DIFF_PANE,
    subcommand: 'diff',
    render,
    refresh,
    reveal,
    scroll,
    noteEdited,
    turnEnded,
    knownPaths,
    toplevel: () => model.repository?.toplevel ?? null,
  }
}

