          rows: data,
          ...(opts.activeId ? { activeId: opts.activeId } : {}),
          ...(opts.rowHoverBg ? { rowHoverBg: opts.rowHoverBg } : {}),
          ...(opts.activeBg ? { activeBg: opts.activeBg } : {}),
