    seg.id ? (
      buttonOf(kit, { key: seg.id, text: seg.t, onPress: seg.onPress ?? (() => {}) })
    ) : (
      <Text key={k} color={seg.c} bold={seg.b} dimColor={seg.dim} italic={seg.i}>
        {seg.t}
      </Text>
    )
