    <Box key={opts.key} flexDirection="column">
      {rows.map((r, i) => (
        <Box
          key={r.key ?? (r.id ? `row:${r.id}` : `${opts.key}:${i}`)}
          flexDirection="row"
          gap={1}
          overflow="hidden"
          flexWrap="nowrap"
