    for (const field of [
      'c',
      'bg',
      'b',
      'dim',
      'i',
      'shrink',
      'id',
      'hoverBg',
      'hoverC',
    ] as const) {
      if (seg[field] !== undefined) Object.assign(clean, { [field]: seg[field] })
    }
    const prev = out[out.length - 1]
    if (prev && !prev.id && !clean.id && !prev.shrink && !clean.shrink && sameStyle(prev, clean)) {
